"""Undo, redo and history (docs/undo.md)."""

from binkeep import journal
from binkeep.bins import normalize
from binkeep.errors import DataError, Refused
from binkeep.report import entry_lines


class Stacks:
    def __init__(self):
        self.done = []
        self.undone = []
        self.dropped = set()
        self.last_undo = {}

    def push_op(self, e):
        self.done.append(e)
        self.dropped.update(x["seq"] for x in self.undone)
        self.undone = []

    def apply(self, e):
        op = e["op"]
        if op in journal.STOCK_OPS:
            self.push_op(e)
        elif op in ("undo", "redo"):
            src, dst = (self.done, self.undone) if op == "undo" else (self.undone, self.done)
            t = e.get("target")
            if not src or isinstance(t, bool) or src[-1]["seq"] != t:
                raise DataError("journal", f"#{e['seq']}: {op} does not match the stacks")
            dst.append(src.pop())
            if op == "undo":
                self.last_undo[t] = e


def _stacks(entries):
    st = Stacks()
    for e in entries:
        st.apply(e)
    return st


def _qty(v):
    if not isinstance(v, int) or isinstance(v, bool):
        raise DataError("journal", "bad quantity")
    return v


def _units(ctx, e):
    q = _qty(e["qty"])
    if e.get("uom") == "pk" and e["sku"] in ctx.items:
        q *= ctx.items[e["sku"]].pack_size
    return q


def _v1_changes(ctx, e):
    """List of (bin, delta or None, absolute) to apply, taking the operation back."""
    op = e["op"]
    n = normalize
    try:
        if op == "receive":
            return [(n(e["bin"]), -_units(ctx, e))]
        if op == "issue":
            return [(n(b), _qty(q)) for b, q in reversed(e["picks"])]
        if op == "move":
            q = _qty(e["qty"])
            return [(n(e["to"]), -q), (n(e["from"]), q)]
    except (KeyError, TypeError, ValueError):
        raise DataError("journal", f"#{e['seq']}: malformed line") from None
    raise DataError("journal", f"#{e['seq']}: cannot undo")


def _step(ctx, store, st, entries, kind, by):
    sku_of = None
    if kind == "undo":
        if not st.done:
            raise Refused("nothing-to-undo", "nothing to undo")
        e = st.done[-1]
        if e["op"] == "fix":
            raise Refused("barrier", "a fix cannot be undone")
        if e.get("v") != 2 and e["op"] == "count":
            raise Refused("irreversible", "format 1 count cannot be undone")
        if e.get("v") == 2:
            try:
                sets = [(f["bin"], f["before"]) for f in reversed(e["effects"])]
            except (KeyError, TypeError):
                raise DataError("journal", f"#{e['seq']}: malformed line") from None
            rel = None
        else:
            rel = _v1_changes(ctx, e)
    else:
        if not st.undone:
            raise Refused("nothing-to-redo", "nothing to redo")
        e = st.undone[-1]
        u = st.last_undo.get(e["seq"])
        try:
            sets = [(f["bin"], f["before"]) for f in reversed(u["effects"])]
        except (KeyError, TypeError):
            raise DataError("journal", f"#{u['seq']}: malformed line") from None
        rel = None
    sku = e.get("sku")
    names = [b for b, _ in (rel if rel is not None else sets)]
    for b in names:
        if b not in ctx.bins:
            raise Refused("unknown-bin", f"no bin {b}")
    effects = []
    for b, v in (rel if rel is not None else sets):
        cur = store.qty(sku, b)
        after = cur + v if rel is not None else _qty(v)
        store.set(sku, b, after, force=True)
        effects.append({"bin": b, "before": cur, "after": after})
    new = journal.entry(journal.next_seq(entries), kind, by, sku, target=e["seq"], effects=effects)
    st.apply(new)
    entries.append(new)
    return new, e


def run(ctx, kind, steps):
    entries = list(ctx.entries)
    st = _stacks(entries)
    store = ctx.store.copy()
    new, lines = [], []
    for _ in range(steps):
        n, e = _step(ctx, store, st, entries, kind, ctx.by)
        new.append(n)
        lines.extend([f"#{n['seq']} {n['op']} {n['sku']} (#{n['target']} {e['op']})"] + entry_lines(n)[1:])
    ctx.commit(store, new)
    return lines


def history(ctx, limit):
    entries = ctx.entries
    st = _stacks(entries)
    undone = {x["seq"] for x in st.undone}
    ops_ = [e for e in entries if e["op"] in journal.STOCK_OPS]
    out = []
    for e in reversed(ops_[-limit:]):
        if e["op"] == "fix":
            s = "barrier"
        elif e["seq"] in undone:
            s = "undone"
        elif e["seq"] in st.dropped:
            s = "dropped"
        else:
            s = "done"
        out.append(f"{e['seq']:>5}  {e['op']:<7}  {e.get('sku', ''):<10}  {s}")
    return out
